/**
 * A closed workspace is gone for every caller that is not the close operation
 * itself. Jobs use the predicate to skip the tenant; services use the assert
 * so a session minted before the close cannot keep reading or writing.
 */
import { isArchived } from "@/lib/soft-delete";
import * as orgRepo from "@/server/repositories/organization-repository";
import { NotFoundError } from "./_support";
import type { OrgId } from "@/types/common";

/** True only when the organization row exists and has been closed. */
export async function isOrganizationClosed(orgId: OrgId): Promise<boolean> {
  const org = await orgRepo.findOrgById(orgId);
  return org !== null && isArchived(org);
}

/**
 * Refuses reads and writes against a closed workspace. A missing organization
 * is the same failure: callers must not be able to tell the two apart by
 * proceeding to query its data.
 */
export async function assertOrganizationOpen(orgId: OrgId): Promise<void> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org || isArchived(org)) {
    throw new NotFoundError("Organization", orgId);
  }
}

