/**
 * Slug lookup for `[orgSlug]` routes. A closed workspace is indistinguishable
 * from a missing one here so nobody can open it; the address stays reserved
 * because `listTakenOrgSlugs` still sees the row.
 */
export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  const org = await orgRepo.findOrgBySlug(slug);
  if (!org || isArchived(org)) return null;
  return org;
}

