input.new_string:
export async function deleteOrganizationAction(
  raw: unknown,
): Promise<ActionResult<Organization>> {
  const parsed = deleteOrganizationSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  // A session from before the close can no longer enter the workspace, so the
  // second attempt never reaches `withAction`'s actor lookup. The conflict is
  // decided here, after the same confirmation check the service applies, and
  // a wrong confirmation still writes nothing.
  const existing = await findOrgById(parsed.data.orgId);
  if (existing !== null && existing.archivedAt !== null) {
    if (existing.slug !== parsed.data.confirmSlug) {
      return toActionResult(
        new Error("The confirmation does not match this organization's slug"),
      );
    }
    try {
      assertNotArchived("Organization", existing.id, existing);
    } catch (error) {
      return toActionResult(error);
    }
  }

  return run(raw);
}

